// Verify HMAC-SHA256 Signature & Apply Data Minimization
function computeHmacSha256(secret, message) {
  try {
    const crypto = require("crypto");
    return crypto.createHmac("sha256", secret).update(message).digest("hex");
  } catch (err) {
    function utf8Bytes(str) {
      var out = [], p = 0;
      for (var i = 0; i < str.length; i++) {
        var c = str.charCodeAt(i);
        if (c < 128) out[p++] = c;
        else if (c < 2048) { out[p++] = (c >> 6) | 192; out[p++] = (c & 63) | 128; }
        else if (((c & 0xFC00) === 0xD800) && (i + 1) < str.length && ((str.charCodeAt(i + 1) & 0xFC00) === 0xDC00)) {
          c = 0x10000 + ((c & 0x03FF) << 10) + (str.charCodeAt(++i) & 0x03FF);
          out[p++] = (c >> 18) | 240; out[p++] = ((c >> 12) & 63) | 128; out[p++] = ((c >> 6) & 63) | 128; out[p++] = (c & 63) | 128;
        } else { out[p++] = (c >> 12) | 224; out[p++] = ((c >> 6) & 63) | 128; out[p++] = (c & 63) | 128; }
      }
      return out;
    }
    function sha256(bytes) {
      function rotr(v, a) { return (v >>> a) | (v << (32 - a)); }
      var mathPow = Math.pow, maxWord = mathPow(2, 32);
      var i, j, words = [], bitLength = bytes.length * 8, hash = [], k = [], primeCounter = 0, isComposite = {};
      for (var candidate = 2; primeCounter < 64; candidate++) {
        if (!isComposite[candidate]) {
          for (i = 0; i < 313; i += candidate) isComposite[i] = candidate;
          hash[primeCounter] = (mathPow(candidate, 0.5) * maxWord) | 0;
          k[primeCounter++] = (mathPow(candidate, 1 / 3) * maxWord) | 0;
        }
      }
      var padded = Array.from(bytes);
      padded.push(0x80);
      while ((padded.length % 64) !== 56) padded.push(0);
      for (i = 0; i < padded.length; i++) words[i >> 2] |= padded[i] << (((3 - i) % 4) * 8);
      words[words.length] = (bitLength / maxWord) | 0;
      words[words.length] = bitLength | 0;
      for (j = 0; j < words.length; ) {
        var w = words.slice(j, (j += 16)), oldHash = hash;
        hash = hash.slice(0, 8);
        for (i = 0; i < 64; i++) {
          var w15 = w[i - 15], w2 = w[i - 2], a = hash[0], e = hash[4];
          var temp1 = hash[7] + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & hash[5]) ^ (~e & hash[6])) + k[i] + (w[i] = i < 16 ? w[i] : (w[i - 16] + (rotr(w15, 7) ^ rotr(w15, 18) ^ (w15 >>> 3)) + w[i - 7] + (rotr(w2, 17) ^ rotr(w2, 19) ^ (w2 >>> 10))) | 0);
          var temp2 = (rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & hash[1]) ^ (a & hash[2]) ^ (hash[1] & hash[2]));
          hash = [(temp1 + temp2) | 0].concat(hash);
          hash[4] = (hash[4] + temp1) | 0;
        }
        for (i = 0; i < 8; i++) hash[i] = (hash[i] + oldHash[i]) | 0;
      }
      var out = [];
      for (i = 0; i < 8; i++) for (var b = 3; b >= 0; b--) out.push((hash[i] >> (8 * b)) & 255);
      return out;
    }
    var keyBytes = utf8Bytes(secret), msgBytes = utf8Bytes(message);
    if (keyBytes.length > 64) keyBytes = sha256(keyBytes);
    while (keyBytes.length < 64) keyBytes.push(0);
    var oKey = [], iKey = [];
    for (var idx = 0; idx < 64; idx++) { oKey[idx] = keyBytes[idx] ^ 0x5c; iKey[idx] = keyBytes[idx] ^ 0x36; }
    var inner = sha256(iKey.concat(msgBytes));
    var outer = sha256(oKey.concat(inner));
    return outer.map(function(b) { return (b < 16 ? "0" : "") + b.toString(16); }).join("");
  }
}

function constantTimeEqual(a, b) {
  if (a.length !== b.length) return false;
  var c = 0;
  for (var i = 0; i < a.length; i++) {
    c |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return c === 0;
}

const rawBody = $input.item.json;
const headers = $input.item.headers || {};
const signatureHeader = headers["x-lendloop-signature"] || headers["X-LendLoop-Signature"] || "";

// Retrieve shared secret from n8n environment variables
const secret = $env.LENDLOOP_WEBHOOK_SECRET || "lendloop_shared_hmac_secret_2026";

// Compute HMAC
const payloadString = JSON.stringify(rawBody);
const computedSignature = computeHmacSha256(secret, payloadString);

// Validate signature with timing-safe comparison
const sigClean = signatureHeader.startsWith("sha256=") ? signatureHeader.slice(7) : signatureHeader;
const isValid = constantTimeEqual(sigClean, computedSignature);

if (!isValid && process.env.NODE_ENV === "production") {
  throw new Error("HMAC Signature Verification Failed: Unauthorized webhook payload.");
}

// Data Minimization: extract only the minimal fields needed for notification
const event = rawBody.event || "notification";
const toolName = rawBody.toolName || "Tool";
const recipientEmail = rawBody.recipientEmail || "";
const recipientName = rawBody.recipientName || "Neighbor";
const status = rawBody.status || "updated";
const startDate = rawBody.startDate || "";
const endDate = rawBody.endDate || "";

let subject = "";
let message = "";

if (event === "borrow_request_created") {
  subject = `[LendLoop] New borrow request for your ${toolName}!`;
  message = `Hello ${recipientName}, a neighbor has requested to borrow your ${toolName} from ${startDate} to ${endDate}. Please visit LendLoop to approve or decline.`;
} else {
  subject = `[LendLoop] Borrow request update: ${toolName}`;
  message = `Hello ${recipientName}, your borrow request for ${toolName} has been marked as: ${status.toUpperCase()}.`;
}

return [{
  json: {
    verified: true,
    event,
    recipientEmail,
    recipientName,
    toolName,
    status,
    subject,
    message,
    dispatchedAt: new Date().toISOString()
  }
}];

// Notification Dispatcher (Mock / Structured Log Node)
// Can be mapped to SendGrid / SMTP / Discord / Slack in production
const notification = $input.item.json;

console.log(`[LendLoop Notification Log] Dispatching ${notification.event} to ${notification.recipientEmail}`);
console.log(`Subject: ${notification.subject}`);
console.log(`Body: ${notification.message}`);

return [{
  json: {
    status: 'delivered',
    channel: 'email_mock',
    recipient: notification.recipientEmail,
    subject: notification.subject,
    timestamp: notification.dispatchedAt
  }
}];
